def solve(grid):
    """
    Transform the input grid according to the discovered rule:
    - Find the number that occurs exactly once (the unique number).
    - Keep that number at its original location.
    - Fill the eight surrounding cells (including diagonals) with the smallest
      integer greater than 1 that appears at least twice in the input.
    - Set all other cells to zero.
    """
    if not grid:
        return []

    n = len(grid)
    m = len(grid[0]) if grid else 0

    # Count occurrences of each non‑zero value
    freq = {}
    for row in grid:
        for v in row:
            if v != 0:
                freq[v] = freq.get(v, 0) + 1

    # Determine the unique number (frequency == 1)
    centre_val = None
    for val, cnt in freq.items():
        if cnt == 1:
            centre_val = val
            break

    # Fallback: if no unique number exists, pick the smallest non‑zero value
    if centre_val is None:
        centre_val = min(v for v in freq.keys() if v != 0)

    # Locate the centre in the grid
    centre_pos = None
    for i in range(n):
        for j in range(m):
            if grid[i][j] == centre_val:
                centre_pos = (i, j)
                break
        if centre_pos:
            break

    # Determine the surround value: smallest integer > 1 with frequency >= 2
    max_val = max(freq.keys()) if freq else 0
    surround_val = None
    for v in range(2, max_val + 2):
        if freq.get(v, 0) >= 2:
            surround_val = v
            break

    # Fallback: if no such value exists, use the smallest integer > 1 present
    if surround_val is None:
        for v in range(2, max_val + 2):
            if v in freq:
                surround_val = v
                break
        if surround_val is None:
            surround_val = 1  # extreme fallback

    # Build the output grid
    out = [[0] * m for _ in range(n)]

    if centre_pos:
        r, c = centre_pos
        out[r][c] = centre_val
        for dr in (-1, 0, 1):
            for dc in (-1, 0, 1):
                if dr == 0 and dc == 0:
                    continue
                nr, nc = r + dr, c + dc
                if 0 <= nr < n and 0 <= nc < m:
                    out[nr][nc] = surround_val

    return out

